// api/hello.js
export function world() {
  return { message: 'Hello, World!' };
}

// Inside any controller method
this.broadcast({
  type: 'announcement',
  message: 'Hello everyone!'
});

// api/chat.js
export function send(message) {
  // Send to everyone except the sender
  this.broadcastOthers({
    type: 'newMessage',
    from: this.clientId,
    text: message
  });
  return { sent: true };
}

