// api/files.js
import fs from 'fs';

export async function upload({ name, type, data }) {
  // data is ArrayBuffer
  const buffer = Buffer.from(data);

  await fs.promises.writeFile(`./uploads/${name}`, buffer);

  return {
    saved: true,
    size: buffer.length
  };
}

// Without error handling - app crashes!
const data = await api.users.get({ id: 'invalid' });

// With error handling - graceful recovery
try {
  const data = await api.users.get({ id: 'invalid' });
} catch (error) {
  console.error('Failed to fetch user:', error.message);
  showErrorToast('User not found');
}

try {
  await api.protected.resource();
} catch (error) {
  switch (error.code) {
    case 'UNAUTHORIZED':
      redirectToLogin();
      break;
    case 'NOT_FOUND':
      show404Page();
      break;
    default:
      showGenericError(error.message);
  }
}

// api-ape handles reconnection automatically!
// But you should know when it happens:
api.onStateChange((state) => {
  if (state === 'connecting') {
    showReconnectingSpinner();
  } else if (state === 'connected') {
    hideSpinner();
    refreshData(); // Re-fetch any stale data
  }
});

// This works even if temporarily disconnected!
async function saveData(data) {
  // Call is buffered if offline, sent when connected
  const result = await api.data.save(data);
  return result;
}

// Show user feedback about connection state
api.onStateChange((state) => {
  if (state === 'disconnected') {
    showBanner('Working offline - changes will sync');
  } else if (state === 'connected') {
    hideBanner();
  }
});

// Get current state
const state = api.state; // 'connected', 'disconnected', etc.

// Listen for state changes
api.onStateChange((newState, oldState) => {
  console.log(`State changed: ${oldState} -> ${newState}`);
});

api.onStateChange((state) => {
  switch (state) {
    case 'offline':
      showOfflineMode();
      break;
    case 'walled':
      showCaptivePortalPrompt();
      // Open captive portal page
      window.open('http://captive.portal.test', '_blank');
      break;
    case 'connecting':
      showReconnectingSpinner();
      break;
    case 'connected':
      showOnlineMode();
      syncPendingChanges();
      break;
    case 'disconnected':
      showDisconnectedWarning();
      break;
  }
});

