export function whoami() {
  return {
    clientId: this.clientId,     // Unique client identifier
    sessionId: this.sessionId,   // Session identifier
    isAuth: this.isAuthenticated,
    authTier: this.authTier,     // 0-3
    browser: this.agent.browser, // 'Chrome', 'Firefox', etc.
    online: this.online()        // Count of connected clients
  };
}

export function notifyAll(message) {
  // Broadcast to everyone except the sender
  this.broadcastOthers({
    type: 'notification',
    from: this.clientId,
    message
  });

  // Also publish to a specific channel
  this.publish.notifications.global({ message });

  return { sent: true, recipients: this.online() - 1 };
}

export function deviceInfo() {
  const { agent } = this;
  return {
    browser: agent.browser,      // 'Chrome'
    browserVersion: agent.browserVersion, // '120.0.0'
    os: agent.os,                // 'macOS'
    osVersion: agent.osVersion,  // '14.2'
    device: agent.device,        // 'desktop'
    isBot: agent.isBot,          // false
    isMobile: agent.isMobile,    // false
    isTablet: agent.isTablet     // false
  };
}

// Check if user has MFA enabled
export function checkMfaStatus() {
  return {
    hasMfa: this.authTier >= 2,
    currentTier: this.authTier
  };
}

// Require MFA for sensitive operations
export function transferFunds(amount, to) {
  if (this.authTier < 2) {
    throw { code: 'MFA_REQUIRED', message: 'Enable MFA to transfer funds' };
  }
  return processTransfer(amount, to);
}

// Server: Generate WebAuthn challenge
export async function startWebAuthnSetup() {
  if (!this.isAuthenticated) throw new Error('Login first');

  const challenge = await auth.webauthn.generateRegistration({
    userId: this.principal.userId,
    userName: this.principal.email
  });

  return challenge;
}

// Client: Complete WebAuthn registration
const challenge = await api.auth.startWebAuthnSetup();
const credential = await navigator.credentials.create({
  publicKey: challenge
});
await api.auth.completeWebAuthnSetup({ credential });

// Server: Generate TOTP secret
export async function startTotpSetup() {
  if (!this.isAuthenticated) throw new Error('Login first');

  const { secret, qrCode } = await auth.totp.generateSecret({
    label: this.principal.email,
    issuer: 'MyApp'
  });

  return { qrCode }; // Display this QR code to user
}

// Server: Verify TOTP code
export async function verifyTotp({ code }) {
  const valid = await auth.totp.verify(this.principal.userId, code);
  if (valid) {
    await auth.elevateToTier2(this.sessionId);
    return { success: true, tier: 2 };
  }
  throw new Error('Invalid code');
}

// Authentication state machine
// Tier 0 (Guest) → Tier 1 (Basic) → Tier 2 (Elevated)

export function getAuthState() {
  return {
    tier: this.authTier,
    isAuthenticated: this.isAuthenticated,
    hasMfa: this.authTier >= 2,
    principal: this.authTier >= 1 ? this.principal : null
  };
}

// Controller that requires elevation
export async function sensitiveOperation(data) {
  // Check current tier
  if (this.authTier < 2) {
    // Return challenge for MFA
    return {
      requiresElevation: true,
      availableMethods: await auth.getMfaMethods(this.principal.userId)
    };
  }

  // User is at Tier 2, proceed with operation
  return performSensitiveOperation(data);
}

// Client handling
const result = await api.account.sensitiveOperation(data);
if (result.requiresElevation) {
  await showMfaPrompt(result.availableMethods);
  // Retry after MFA
}

// Tier 3 protects the most sensitive operations
export async function approveHighValueTransaction(txId) {
  if (this.authTier < 3) {
    throw {
      code: 'TIER3_REQUIRED',
      message: 'This operation requires Tier 3 authentication'
    };
  }

  // User has proven they control 2-of-3 key shares
  return await processHighValueTransaction(txId);
}

// Server: Initialize Tier 3 for user
export async function setupTier3() {
  if (this.authTier < 2) {
    throw new Error('Enable MFA first');
  }

  const { deviceShare, recoveryShare } = await auth.shamir.generateShares({
    userId: this.principal.userId,
    threshold: 2,  // Need 2-of-3 shares
    total: 3
  });

  // Server share is stored automatically
  // Return device share and recovery share to client
  return {
    deviceShare,  // Store in device secure storage
    recoveryShare // User must write this down!
  };
}

// Server: Verify Tier 3
export async function verifyTier3({ deviceShare, recoveryShare }) {
  // User provides device share (from secure storage)
  // and optionally recovery share (if device unavailable)

  const valid = await auth.shamir.verify({
    userId: this.principal.userId,
    shares: [deviceShare, recoveryShare].filter(Boolean)
  });

  if (valid) {
    await auth.elevateToTier3(this.sessionId);
    return { tier: 3, elevated: true };
  }

  throw new Error('Invalid shares');
}

