import { ape } from 'api-ape';
import loggingPlugin from './plugins/logging';
import metricsPlugin from './plugins/metrics';
import rateLimitPlugin from './plugins/rateLimit';

ape(server, {
  where: 'api',
  plugins: [
    loggingPlugin,
    metricsPlugin,
    rateLimitPlugin
  ]
});

// Without Forest: Single server
// this.broadcast() only reaches clients on THIS server

// With Forest: Multi-server cluster
// this.broadcast() reaches clients on ALL servers
ape(server, {
  where: 'api',
  forest: {
    adapter: 'redis',
    config: { url: 'redis://localhost:6379' }
  }
});

// Redis adapter (recommended)
forest: {
  adapter: 'redis',
  config: {
    url: process.env.REDIS_URL,
    prefix: 'api-ape:',  // Key prefix
    ttl: 3600            // Session TTL
  }
}

// PostgreSQL adapter
forest: {
  adapter: 'postgres',
  config: {
    connectionString: process.env.DATABASE_URL,
    channel: 'api_ape_sync'
  }
}

// These work across ALL servers in the cluster:

// Broadcast to all clients everywhere
this.broadcast({ type: 'globalAnnouncement', text: 'Hello cluster!' });

// Publish to subscribers on any server
this.publish.notifications.all({ message: 'New feature!' });

// Get total online count across cluster
const totalOnline = this.online(); // Returns cluster-wide count

// Send to specific client (even on different server)
ape.sendTo(clientId, { type: 'directMessage', text: 'Hi!' });

// Architecture overview
//
// Load Balancer (sticky sessions)
//        │
//    ┌───┴───┬───────┐
//    │       │       │
//   API-1  API-2  API-3
//    │       │       │
//    └───┬───┴───────┘
//        │
//    Redis (Forest)
//        │
//    Database

# Nginx example with sticky sessions
upstream api_cluster {
    ip_hash;  # Sticky sessions based on IP
    server api-1:3000;
    server api-2:3000;
    server api-3:3000;
}

server {
    location /api/ape {
        proxy_pass http://api_cluster;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

// api/health.js
export function check() {
  return {
    status: 'healthy',
    timestamp: Date.now(),
    connections: this.online(),
    uptime: process.uptime()
  };
}

export async function deep() {
  // Check all dependencies
  const checks = await Promise.all([
    checkRedis(),
    checkDatabase(),
    checkExternalApi()
  ]);

  const healthy = checks.every(c => c.ok);
  return {
    status: healthy ? 'healthy' : 'degraded',
    checks
  };
}
